		// Octet = Digit{1,3}
		static int Recognize_Octet(global::System.ReadOnlySpan<char> text, int pos)
		{
			global::System.Span<int> bt = stackalloc int[48];

			var sp    = 0;
			var saved = 0;
			var p     = pos;
			var r     = 0;
			var c0    = 0;
