						// and so the one that goes through the switch again.
						continue;

					case 2:
						// Digit{1,3} — stop, and check the count
						c0 = saved;

						if (c0 < 1)
							goto case 1;

						goto case 0;

					case 3:
						// Digit{1,3} — take another, or leave stopping open
						if (c0 >= 3)
						{
							saved = c0;
							goto case 2;
						}

