						// Digit{1,3} — one more taken
						c0++;
						goto case 3;

					case 5:
						// Digit{1,3} — start counting
						c0 = 0;
						goto case 3;

					case 6:
						// Digit
						r = Recognize_Digit(text, p);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					default:
						return -1;
				}
			}
		}

