			var state = 2;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					return -1;

				case 2:
					// ['0'..'9']
					if (p >= text.Length)
						goto case 1;

					c = text[p];

					if (!((c >= '0' && c <= '9')))
						goto case 1;

					p++;
					goto case 0;

				default:
					return -1;
			}
		}

